"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";

import { cn } from "@/lib/utils";
import { controlChecked, copperRimChecked, focusRing, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Burnished Checkbox: a 1.25rem box with a 0.375rem corner, pressed into a
 * recessed well while off. Checked or mixed, it rises as the primary's cream
 * bevel inside a thin copper rim and shows a dark tick or dash. Base UI owns
 * the checked state, so a controlled parent passes `checked` straight through.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex size-5 shrink-0 items-center justify-center rounded-sm border-2 border-transparent text-primary-foreground",
        wellInset,
        "transition-[box-shadow,background-image] duration-fast ease-(--ease-out)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        controlChecked,
        copperRimChecked,
        "data-[indeterminate]:bg-(image:--fill-primary) data-[indeterminate]:shadow-(--bevel-primary)",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        keepMounted
        data-slot="checkbox-indicator"
        className="size-full grid place-items-center text-current data-[unchecked]:opacity-0 transition-opacity duration-fast"
      >
        {indeterminate ? (
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-3">
            <path d="M3.5 8h9" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
          </svg>
        ) : (
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-3">
            <path
              d="M3 8.5 6.25 11.5 13 4.5"
              stroke="currentColor"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
